import sqlite3, sqlite_vec, numpy as np, time
from collections import defaultdict, Counter
from sklearn.cluster import AgglomerativeClustering
conn = sqlite3.connect("file:data/app.db?mode=ro", uri=True)
conn.enable_load_extension(True); sqlite_vec.load(conn)
rows = conn.execute("""SELECT g.id, g.source_item_id, g.category, g.feedback_type, s.vehicle_model_id, s.market_code, s.checkpoint, e.embedding
 FROM signal g JOIN source_item s ON s.id=g.source_item_id JOIN signal_embedding e ON e.rowid=g.id
 WHERE g.extractor_version='extract-v3' ORDER BY g.id""").fetchall()
print(len(rows))
S=[dict(id=r[0],src=r[1],cat=r[2],pol='like' if r[3]=='like' else 'improve',d=r[4],mk=r[5],cp=r[6]) for r in rows]
X=np.stack([np.frombuffer(r[7],dtype=np.float32) for r in rows]); X/=np.linalg.norm(X,axis=1,keepdims=True)
np.save
def clus(idx,t):
    if len(idx)==1: return np.zeros(1,int)
    return AgglomerativeClustering(n_clusters=None,metric='cosine',linkage='average',distance_threshold=t).fit_predict(X[idx])
groups=defaultdict(list)
for i,s in enumerate(S): groups[(s['d'],s['pol'],s['cat'])].append(i)
for t in (0.30,0.35,0.40,0.45):
    res=defaultdict(lambda: Counter())
    for k,idx in groups.items():
        idx=np.array(idx); lab=clus(idx,t)
        for l in set(lab):
            m=idx[lab==l]; nv=len({S[i]['src'] for i in m})
            c=res[k[0]]; c['clusters']+=1; c['single']+= (len(m)==1); 
            if nv>=3: c['find']+=1; c['cov']+=len(m); c['max']=max(c['max'],nv)
            c['sig']+=len(m)
    for d,c in sorted(res.items()):
        print(t,d,dict(clusters=c['clusters'],singletons=c['single'],sing_share=round(c['single']/c['sig'],3),findings=c['find'],coverage=round(c['cov']/c['sig'],3),maxverb=c['max']))
EOF

